<?php
$kg=static fn($n)=>number_format((float)$n,3,',',' ');
$canOperate=Auth::currentSiteId()===null||Auth::currentSiteId()===$site;
$rawStock=array_values(array_filter($raw,static fn($r)=>(float)$r['quantity_kg']>0));
$finishedCold=array_values(array_filter($finished,static fn($r)=>(float)$r['cold_kg']>0));
$rawWeight=array_sum(array_column($rawStock,'quantity_kg'));
$finishedWeight=array_sum(array_column($finishedCold,'cold_kg'));
$counterWeight=array_sum(array_column($counterStocks,'quantity_kg'));
$activeCounters=count(array_filter($counters,static fn($c)=>$c['status']==='active'));
$pendingOrders=count(array_filter($orders,static fn($o)=>$o['status']==='results_submitted'));
$activeOrders=count(array_filter($orders,static fn($o)=>in_array($o['status'],['in_progress','results_submitted'],true)));
$receiptCount=count($incoming)+count($pending);
$stockLabel=static function($r){if($r['expiry_date']<date('Y-m-d'))return 'DLC dépassée';if(in_array($r['status'],['available','reserved'],true))return (float)$r['reserved_kg']>0?'Avec réservation':'Disponible';return ['available'=>'Disponible','reserved'=>'Avec réservation','quarantine'=>'Quarantaine','rejected'=>'Refusé','cancelled'=>'Annulé','in_transit'=>'En transit','depleted'=>'Épuisé'][$r['status']]??$r['status'];};
$stages=[
 'receipts'=>['Réceptions',(string)$receiptCount,'à traiter',count($incoming).' en route · '.count($pending).' à contrôler','Recevoir les carcasses et vérifier leur conformité.','butchery/receipts','Ouvrir les réceptions'],
 'cold-room'=>['Chambre froide',$kg($rawWeight+$finishedWeight),'kg physiques',$kg($rawWeight).' kg de carcasses · '.$kg($finishedWeight).' kg de produits','Suivre les carcasses et les produits conservés au froid.','butchery/cold-room','Ouvrir la chambre froide'],
 'production'=>['Transformation',(string)$activeOrders,'en cours',$pendingOrders.' à valider · '.count($orders).' au total','Découper les carcasses et répartir les produits obtenus.','butchery/production','Ouvrir les transformations'],
 'counters'=>['Comptoirs et ventes',$kg($counterWeight),'kg aux comptoirs',$activeCounters.' comptoir(s) actif(s)','Approvisionner les comptoirs et enregistrer les ventes.','butchery/counters','Ouvrir les comptoirs'],
];
$details=[];
$details['receipts']=['headers'=>['Référence / lot','Origine','Poids (kg)','DLC','Étape'],'rows'=>[]];
foreach($incoming as$r)$details['receipts']['rows'][]=[$r['transfer_number'].' · '.$r['batch_number'],$r['source_name'],$kg($r['quantity_kg']),$r['expiry_date'],'À réceptionner'];
foreach($pending as$r)$details['receipts']['rows'][]=[$r['receipt_number'].' · '.$r['batch_number'],$r['source_name'],$kg($r['quantity_kg']),$r['expiry_date'],'Contrôle à effectuer'];
$details['cold-room']=['headers'=>['Lot / produit','Type','Physique au froid (kg)','Réservé (kg)','DLC','État'],'rows'=>[]];
foreach($rawStock as$r)$details['cold-room']['rows'][]=[$r['lot_number'].' · '.$r['item_name'],'Carcasse / matière',$kg($r['quantity_kg']),$kg($r['reserved_kg']),$r['expiry_date'],$stockLabel($r)];
foreach($finishedCold as$r)$details['cold-room']['rows'][]=[$r['lot_number'].' · '.$r['item_name'],'Produit transformé',$kg($r['cold_kg']),$kg($r['reserved_kg']),$r['expiry_date'],$stockLabel($r)];
$details['production']=['headers'=>['Référence','Fiche','Date','Matière (kg)','Produits (kg)','État'],'rows'=>[]];
foreach($orders as$r)$details['production']['rows'][]=[$r['order_number'],$r['recipe_name'],$r['production_date'],$kg($r['actual_input_kg']),$kg((float)$r['output_kg']+(float)$r['co_product_kg']),['in_progress'=>'En cours','results_submitted'=>'À valider','validated'=>'Validée','cancelled'=>'Annulée'][$r['status']]??$r['status']];
$details['counters']=['headers'=>['Comptoir','Produit / lot','Poids (kg)','DLC','État'],'rows'=>[]];
foreach($counterStocks as$r)$details['counters']['rows'][]=[$r['counter_name'],$r['item_name'].' · '.$r['lot_number'],$kg($r['quantity_kg']),$r['expiry_date'],$r['expiry_date']<date('Y-m-d')?'DLC dépassée · vente bloquée':($r['counter_status']!=='active'?'Comptoir inactif':(['available'=>'Disponible','reserved'=>'Avec réservation','quarantine'=>'Quarantaine','rejected'=>'Refusé','depleted'=>'Épuisé'][$r['lot_status']]??$r['lot_status']))];
?>
<div class="butchery-home">
<header class="ui-page-header"><span class="butchery-home-icon" aria-hidden="true"><i class="bi bi-shop"></i></span><div class="ui-page-header__content"><p class="section-label">BOUCHERIE · VUE D’ENSEMBLE</p><h2>Ma boucherie</h2><p>De la réception des carcasses à la vente au comptoir.</p></div><div class="ui-page-header__actions"><span class="ui-status ui-status--neutral">Site Boucherie</span><a class="btn-secondary" href="<?=e(base_url('butchery/receipts'))?>">Gérer les réceptions</a><?php if($canOperate&&Auth::can('butchery','create',$site)):?><a class="btn-primary" href="<?=e(base_url('butchery/counters'))?>"><i class="bi bi-shop" aria-hidden="true"></i> Accéder aux ventes</a><?php endif;?></div></header>
<?php if($success):?><p class="app-alert app-alert-success" role="status"><?=e($success)?></p><?php endif;?><?php if($error):?><p class="app-alert app-alert-error" role="alert"><?=e($error)?></p><?php endif;?>
<?php if(!$canOperate):?><div class="app-alert flow-context"><p>Vue du stock Boucherie. Sélectionnez ce site pour enregistrer des opérations.</p><form method="post" action="<?=e(base_url('context/site'))?>" data-ajax="false"><?=csrf_field()?><input type="hidden" name="site_id" value="<?=e($site)?>"><input type="hidden" name="_return_to" value="<?=e(base_url('butchery'))?>"><button class="btn-primary" type="submit">Travailler sur Boucherie</button></form></div><?php endif;?>
<?php if($receiptCount||$pendingOrders):?><div class="butchery-home-tasks" role="status"><div><strong>À traiter</strong><p><?=$receiptCount?> réception(s) · <?=$pendingOrders?> transformation(s) à valider</p></div><div><?php if($receiptCount):?><button class="btn-secondary" type="button" data-workspace-modal-open="butchery-overview-receipts" aria-haspopup="dialog">Voir les réceptions</button><?php endif;?><?php if($pendingOrders):?><a class="btn-secondary" href="<?=e(base_url('butchery/production?status=results_submitted'))?>">Voir les validations</a><?php endif;?></div></div><?php endif;?>
<div class="plot-card-grid butchery-stage-grid">
<?php $number=0;foreach($stages as$key=>[$label,$value,$unit,$summary,$description,$path,$action]):$number++;?>
<article class="plot-card butchery-stage-card"><div class="plot-card-visual"><img src="<?=e(asset_url('illustrations/butchery/'.$key.'.svg'))?>" width="288" height="160" alt="" aria-hidden="true"></div><div class="plot-card-body"><p class="section-label">ÉTAPE <?=$number?></p><h3><?=e($label)?></h3><p class="butchery-stage-description"><?=e($description)?></p><p class="butchery-stage-value"><strong><?=e($value)?></strong><span><?=e($unit)?></span></p><p class="butchery-stage-summary"><?=e($summary)?></p><div class="plot-card-actions"><button type="button" class="btn-secondary" data-workspace-modal-open="butchery-overview-<?=e($key)?>" aria-haspopup="dialog" aria-controls="butchery-overview-<?=e($key)?>" aria-label="<?=e('Voir les détails : '.$label)?>">Voir les détails <i class="bi bi-arrow-right" aria-hidden="true"></i></button></div></div></article>
<?php endforeach;?></div>
<p class="butchery-home-note">Les poids affichés représentent le stock physique, y compris les réservations et les lots bloqués. Les ventes se font uniquement depuis les comptoirs.</p>
<?php foreach($stages as$key=>[$label,$value,$unit,$summary,$description,$path,$action]):$listing=$details[$key];?>
<section id="butchery-overview-<?=e($key)?>" class="entity-modal workspace-entity-modal feed-editor butchery-overview-modal" role="dialog" aria-modal="true" aria-hidden="true" aria-labelledby="butchery-overview-title-<?=e($key)?>"><header><div><p class="page-kicker">BOUCHERIE · DÉTAILS</p><h2 id="butchery-overview-title-<?=e($key)?>"><?=e($label)?></h2><p><?=e($summary)?></p></div><button type="button" class="modal-close" data-workspace-modal-close aria-label="Fermer les détails">×</button></header><div class="feed-form-body">
<?php if($key==='production'):?><p class="butchery-home-note">Historique des transformations. Les résultats deviennent disponibles après validation.</p><?php endif;?>
<div class="table-responsive"><table class="enterprise-table" data-search-placeholder="<?=e('Rechercher dans : '.$label)?>" aria-label="<?=e('Détails : '.$label)?>"><thead><tr><?php foreach($listing['headers'] as$heading):?><th scope="col"><?=e($heading)?></th><?php endforeach;?></tr></thead><tbody><?php foreach($listing['rows'] as$line):?><tr><?php foreach($line as$value):?><td><?=e($value)?></td><?php endforeach;?></tr><?php endforeach;?><?php if(!$listing['rows']):?><tr><td colspan="<?=count($listing['headers'])?>">Aucun élément à afficher pour le moment.</td></tr><?php endif;?></tbody></table></div>
<?php if($key==='counters'):?><details class="butchery-home-sales"><summary>Dernières ventes · <?=count($sales)?></summary><div class="table-responsive"><table class="enterprise-table" aria-label="Dernières ventes" data-search-placeholder="Rechercher une vente"><thead><tr><th>Date / référence</th><th>Comptoir</th><th>Produit</th><th>Poids (kg)</th><th>Montant</th></tr></thead><tbody><?php foreach($sales as$r):?><tr><td><?=e($r['sold_at'].' · '.$r['sale_number'])?></td><td><?=e($r['counter_name']?:'Vente historique')?></td><td><?=e($r['item_name'])?></td><td><?=$kg($r['quantity_kg'])?></td><td><?=e(number_format((float)$r['quantity_kg']*(float)$r['unit_price'],2,',',' '))?></td></tr><?php endforeach;?><?php if(!$sales):?><tr><td colspan="5">Aucune vente enregistrée.</td></tr><?php endif;?></tbody></table></div></details><?php endif;?>
</div><footer><button type="button" class="btn-secondary" data-workspace-modal-close>Fermer</button><a class="btn-primary" href="<?=e(base_url($path))?>"><?=e($action)?> <i class="bi bi-arrow-right" aria-hidden="true"></i></a></footer></section>
<?php endforeach;?>
</div>
